#[test]#[ignore = "requires: local evidence roots (snapshot JSON holds absolute D:\\ paths + SHA pins; only runnable on the original machine)"] fn actual_two_cell_move_rechecks_collision_prequeues_each_step_then_arrives(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let d=a::nad(&fixed.bytes("resources/appearance-dependencies.nad")).unwrap();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let trace:Value=serde_json::from_slice(&fixed.bytes("appearance-layer-trace.json")).unwrap();let banks=BTreeMap::from([(76,fixed.bank(&d,&trace,76)),(84,fixed.bank(&d,&trace,84)),(88,fixed.bank(&d,&trace,88))]);let(assets,plan,mut extra)=native::assets();let effect=fire_fixture::effect(&plan,&mut extra);let index=assets.effect_records().iter().position(|v|v.effect.sprite_id==38).unwrap();let initial=WorldCell{x:32755,y:32788};let middle=WorldCell{x:32755,y:32789};let target=WorldCell{x:32755,y:32790};let init=RoofInputs{local_actor_pointer_matches:Some(true),old_cell:Some(initial),new_cell:Some(initial),no_dynamic_cell_entries:Some(true),source_initialized_tiles:Some(true),scheduler_sample_ms:Some(500)};
 let scene=super::super::Model::new(true,b,b.observed,&d,&banks,&assets,&plan,&effect,index,initial,&init,&fire_first::create(),fixture::ordinary(),fixture::end(),Some(projection(camera()).unwrap()),Some(22)).unwrap();let movement=movement::Model::new(true,&d,b,b.observed,initial,Some(camera())).unwrap();let mut m=Model::new(scene,movement,b,b.observed).unwrap();let mouse=(-500..=500).flat_map(|y|(-500..=500).map(move|x|crate::modern_lito::world_map::PixelPoint{x,y})).find(|p|movement::mouse_cell(*p,camera().center).unwrap()==target).unwrap();let start=movement::Start{at:Some(1000),mouse:Some(mouse),source_collision_blocked:Some([false;8]),source_final_passable:Some(true),fresh_schedule_samples:Some(vec![1000;3]),runtime:runtime(b)};
 let out=project.join("target/r461-two-cell-locomotion-scene-cpu");fs::create_dir_all(&out).unwrap();let mut images=vec![];let mut rows=vec![];let mut source=vec![];let mut held=None;let mut negative=0;let(f,s)=m.start(b,b.observed,&start,&draw()).unwrap();assert_eq!(s.added.iter().map(|v|v.at).collect::<Vec<_>>(),vec![1166,1332,1498]);save(&m,b,f,Some(s),&out,&mut images,&mut rows,&mut source,&mut held);
 loop{let ticket=m.scene.next(b,b.observed).unwrap();let e=ticket.event;if e.at>3080{break;}if e.at>2500&&m.scene.fire_index.is_some(){let q=super::super::super::RemoveInputs{sector_unload_reached:Some(true),registry_actor_matches:Some(true),sector_id_range_contains_actor:Some(true),no_opcode11:Some(true),extra_draw_pointers_absent:Some(true),actor_global_pointers_differ:Some(true)};let f=m.scene.remove_fire(b,b.observed,2500,&q,&draw()).unwrap();save(&m,b,f,None,&out,&mut images,&mut rows,&mut source,&mut held);continue;}
  let(f,s)=if matches!(e.kind,Kind::Locomotion(_)){let t=m.movement.next(b,b.observed).unwrap();let reads=if e.at==1664{3}else if t.kind==movement::Kind::Step&&e.at!=1498&&e.at!=2162{0}else{1};let q=movement::Callback{dispatch:Some(e.at),timer_removed:Some(true),callback_owner_matches:Some(true),fresh_schedule_samples:Some(vec![e.at;reads]),queue_before_pop:Some(if t.kind==movement::Kind::IdlePop{1}else{0}),runtime:runtime(b),source_collision_blocked:if e.at==1664{Some([false;8])}else{None},source_final_passable:if e.at==1664{Some(true)}else{None}};
   if e.at==1664{let before=m.scene.next(b,b.observed).unwrap().event;let cell=m.movement.cell(b,b.observed).unwrap();assert_eq!(cell,middle);for i in 0..4{let mut bad=q.clone();match i{0=>bad.source_collision_blocked=None,1=>bad.source_final_passable=None,2=>bad.source_collision_blocked=Some([true;8]),_=>bad.fresh_schedule_samples=Some(vec![e.at])};assert!(m.dispatch(b,b.observed,&ticket,&bad,None,&draw()).is_err());assert_eq!(m.scene.next(b,b.observed).unwrap().event,before);assert_eq!(m.movement.cell(b,b.observed).unwrap(),cell);negative+=1;}let mut late=q.clone();late.fresh_schedule_samples=Some(vec![1664,1665,1666]);let p=m.movement.prepare_callback(b,b.observed,t,&late).unwrap();assert_eq!(p.step.added.iter().map(|v|v.at).collect::<Vec<_>>(),vec![1830,1997,2164]);assert_eq!(p.step.cell,middle);assert!(!p.step.cell_committed);assert_eq!(p.step.wire_move,Some((middle,4)));}
   let roof=if e.at==1498{Some(roof_move(initial,middle,e.at,2))}else if e.at==2162{Some(roof_move(middle,target,e.at,1))}else{None};let(f,s)=m.dispatch(b,b.observed,&ticket,&q,roof.as_ref(),&draw()).unwrap();assert!(m.dispatch(b,b.observed,&ticket,&q,roof.as_ref(),&draw()).is_err());negative+=1;if e.at==1664{assert_eq!(s.added.iter().map(|v|v.at).collect::<Vec<_>>(),vec![1830,1996,2162]);assert_eq!((s.frame,s.bank,s.sub),(1,76,1));assert_eq!(s.cell,middle);assert!(s.active_move);}if e.at==2328{assert!(!s.active_move);assert_eq!(s.cell,target);assert_eq!(s.added[0].at,2912);}(f,Some(s))}
  else{let q=match e.kind{Kind::FireFirst=>{let mut q=fire_first::input();q.static_source_roofs=Some(false);Inputs::FireFirst(q)},Kind::FireAdvance=>{let mut q=fire_fixture::continuation(e.at,m.scene.fire.queued_repeat);q.callback.static_source_roofs=Some(false);Inputs::FireAdvance(q)},Kind::Roof(_)=>{let t=m.scene.roof.next(b,b.observed).unwrap();let mut q=roof::TickInputs{timer_removed_before_callback:Some(true),callback_group_matches:Some(true),dispatch_ms:Some(e.at),fresh_schedule_samples:Some(vec![])};if m.scene.roof.prepare_tick(b,b.observed,&t,&q).is_err(){q.fresh_schedule_samples=Some(vec![e.at]);}Inputs::Roof(q)},_=>panic!("Legacy player path unavailable")};(m.scene.dispatch(b,b.observed,&ticket,q,&draw()).unwrap(),None)};save(&m,b,f,s,&out,&mut images,&mut rows,&mut source,&mut held);
 }
 let committed=source.iter().filter(|v|v["cell_committed"]==true).map(|v|(v["clock"].as_u64().unwrap(),v["cell"].clone())).collect::<Vec<_>>();assert_eq!(committed,vec![(1498,json!([middle.x,middle.y])),(2162,json!([target.x,target.y]))]);assert_eq!(source.iter().filter(|v|v["wire"].is_array()).map(|v|v["clock"].as_u64().unwrap()).collect::<Vec<_>>(),vec![1000,1664]);assert_eq!(m.movement.cell(b,b.observed).unwrap(),target);assert_eq!(source.last().unwrap()["clock"],json!(3080));let held=held.take().unwrap();assert_eq!(m.scene.next(b,b.observed).unwrap().event.at,3248);m.retire();assert!(held.view(&m.scene,b,b.observed).is_err());assert!(m.scene.next(b,b.observed).is_err());assert!(m.movement.next(b,b.observed).is_err());negative+=3;
 fs::write(project.join("logs/continuation-20261003/r461-two-cell-locomotion-details.json"),serde_json::to_vec_pretty(&json!({"state":"SOURCE_TWO_CELL_PLAYER_CARRY_RESELECT_PREQUEUE_THEN_FINAL_ARRIVAL_PRIVATE_SCENE","images":images,"rows":rows,"source_moves":source,"CPU_frames":images.len(),"negative_cases":negative,"source_cells":[[initial.x,initial.y],[middle.x,middle.y],[target.x,target.y]],"source_roof_group_sets":[[],[136,168],[136]],"first_step_prequeued":[1166,1332,1498],"second_step_source_start1664_prequeued":[1830,1996,2162],"only_source_end0_cell_writes":[1498,2162],"final_arrival2328_idle2912":true,"per_step_source_collision_recheck_required":true,"preview_distinct_fresh_clocks":[1830,1997,2164],"wire_start_records_not_sent":[1000,1664],"unexecuted_future3248_retired":true,"audio_UI_wire_not_executed":true,"runtime_inputs_observed":false,"full_native_locomotion_execution_qualified":false,"renderer_LOADED":false,"GUI":0,"input_pins":fixed.used.into_inner(),"extra_input_pins":extra})).unwrap()).unwrap();
}
fn roof_move(old:WorldCell,new:WorldCell,at:u32,reads:usize)->roof::MoveInputs{roof::MoveInputs{actor:RoofInputs{local_actor_pointer_matches:Some(true),old_cell:Some(old),new_cell:Some(new),no_dynamic_cell_entries:Some(true),source_initialized_tiles:Some(true),scheduler_sample_ms:Some(at)},fresh_schedule_samples:Some(vec![at;reads])}}
fn save(m:&Model<'_>,b:&Binding,f:Frame,s:Option<movement::Step>,out:&Path,images:&mut Vec<Value>,rows:&mut Vec<Value>,source:&mut Vec<Value>,held:&mut Option<Frame>){if let Some(old)=held.take(){assert!(old.view(&m.scene,b,b.observed).is_err());}images.push(fixture::png(&out.join(format!("{:02}-{}-{}.png",images.len(),f.clock,f.kind.replace(|c:char|!c.is_ascii_alphanumeric(),"_"))),f.view(&m.scene,b,b.observed).unwrap().rgba(),1024,768));rows.push(json!({"clock":f.clock,"kind":f.kind,"player":f.player_frame,"fire":f.fire_frame,"RGBA_sha256":images.last().unwrap()["RGBA_sha256"]}));if let Some(s)=s{source.push(json!({"clock":s.at,"frame":s.frame,"bank":s.bank,"sub":s.sub,"cell":[s.cell.x,s.cell.y],"cell_committed":s.cell_committed,"active_move":s.active_move,"wire":s.wire_move.map(|(c,h)|(c.x,c.y,h)),"prequeued":s.added.iter().map(|v|v.at).collect::<Vec<_>>(),"camera_center":[s.camera.center.x,s.camera.center.y],"camera_offset":[s.camera.offset.x,s.camera.offset.y]}));}*held=Some(f);}
